import{_ as a,c as e,o as r,ae as s}from"./chunks/framework.Cd-3tpCq.js";const g=JSON.parse('{"title":"Cart Workflow (Shop)","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/shop/cart.md","filePath":"api/workflows/shop/cart.md"}'),o={name:"api/workflows/shop/cart.md"};function i(n,t,d,p,l,h){return r(),e("div",null,t[0]||(t[0]=[s(`<h1 id="cart-workflow-shop" tabindex="-1">Cart Workflow (Shop) <a class="header-anchor" href="#cart-workflow-shop" aria-label="Permalink to &quot;Cart Workflow (Shop)&quot;">​</a></h1><p>Build a cart for a guest or a logged-in customer: create/obtain the cart, add and update items, apply coupons, and merge a guest cart into the customer cart at login.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A valid storefront key (<a href="/api/setup.html">Setup</a>, <a href="/api/authentication.html">Authentication</a>).</li><li>For the customer path: a logged-in customer (<a href="/api/rest-api/shop/customers/customer-login.html">Customer login</a>).</li></ul><p><strong>When does a merge happen?</strong> A guest adds items to a guest cart, then decides to log in. On login you call <strong>mergeCart</strong> with the guest cart token — the guest cart&#39;s items are merged into the customer&#39;s own cart so nothing is lost.</p><h2 id="dependency-diagram" tabindex="-1">Dependency diagram <a class="header-anchor" href="#dependency-diagram" aria-label="Permalink to &quot;Dependency diagram&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  key[Storefront key&lt;br/&gt;ask user] --&gt; who{Customer&lt;br/&gt;logged in?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  who -- guest --&gt; gcart[POST create-cart&lt;br/&gt;guest cart token]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  who -- customer --&gt; login[POST customer login]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gcart --&gt; add[POST add-to-cart]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  add --&gt; decide{Guest logs&lt;br/&gt;in later?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  decide -- yes --&gt; merge[mergeCart&lt;br/&gt;guest cart into customer cart]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  decide -- no --&gt; upd</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  login --&gt; merge</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  merge --&gt; upd[POST update-cart-item]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  add --&gt; coupon[POST apply-coupon]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  upd --&gt; read[GET get-cart]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  coupon --&gt; read</span></span></code></pre></div><h2 id="ordered-call-table" tabindex="-1">Ordered call table <a class="header-anchor" href="#ordered-call-table" aria-label="Permalink to &quot;Ordered call table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Step</th><th>Endpoint</th><th>Depends on</th><th>Note</th></tr></thead><tbody><tr><td>1</td><td>Create guest cart</td><td><a href="/api/rest-api/shop/cart/create-cart.html">POST create-cart</a> · <a href="/api/graphql-api/shop/cart.html">GraphQL</a></td><td>storefront key</td><td>Guest path only; returns a cart token</td></tr><tr><td>2</td><td>Customer login</td><td><a href="/api/rest-api/shop/customers/customer-login.html">POST login</a></td><td>storefront key</td><td>Customer path; after login, merge the guest cart (step 3)</td></tr><tr><td>3</td><td>Merge guest cart</td><td><a href="/api/rest-api/shop/cart/merge-cart.html">POST merge-cart</a> · <a href="/api/graphql-api/shop/mutations/merge-cart.html">GraphQL</a></td><td>a guest cart id + a logged-in customer (customer Bearer token)</td><td>Merges the guest cart&#39;s items into the customer cart so nothing is lost</td></tr><tr><td>4</td><td>Add item</td><td><a href="/api/rest-api/shop/cart/add-to-cart.html">POST add-to-cart</a> · <a href="/api/graphql-api/shop/cart.html">GraphQL</a></td><td>cart (guest token or logged-in customer)</td><td>Same endpoint for both paths</td></tr><tr><td>5</td><td>Update item qty</td><td><a href="/api/rest-api/shop/cart/update-cart-item.html">POST update-cart-item</a></td><td>an item in the cart</td><td></td></tr><tr><td>6</td><td>Apply coupon</td><td><a href="/api/rest-api/shop/cart/apply-coupon.html">POST apply-coupon</a></td><td>an item in the cart</td><td>Remove with <a href="/api/rest-api/shop/cart/remove-coupon.html">remove-coupon</a></td></tr><tr><td>7</td><td>Read cart</td><td><a href="/api/rest-api/shop/cart/get-cart.html">GET get-cart</a> · <a href="/api/graphql-api/shop/cart.html">GraphQL</a></td><td>any cart mutation</td><td>Totals, items, applied coupon</td></tr></tbody></table><blockquote><p><strong>GraphQL equivalents:</strong> the table links REST paths. Each step has a GraphQL operation (<code>createCartToken</code>, <code>createAddProductInCart</code>, <code>createUpdateCartItem</code>, <code>createApplyCoupon</code>, <code>createMergeCart</code>, <code>createReadCart</code>).</p></blockquote><h2 id="end-to-end-sequence" tabindex="-1">End-to-end sequence <a class="header-anchor" href="#end-to-end-sequence" aria-label="Permalink to &quot;End-to-end sequence&quot;">​</a></h2><ul><li><strong>Guest:</strong> create-cart → add-to-cart → apply-coupon → get-cart.</li><li><strong>Guest who then logs in:</strong> create-cart (guest) → add-to-cart → login → <strong>merge-cart</strong> → get-cart.</li></ul><p>Follow each linked endpoint page for the exact request / response body.</p><h2 id="customize" tabindex="-1">Customize <a class="header-anchor" href="#customize" aria-label="Permalink to &quot;Customize&quot;">​</a></h2><p>To change cart behavior on the server, see <a href="/api/workflows/customization/">Customization → Shop</a>.</p>`,15)]))}const u=a(o,[["render",i]]);export{g as __pageData,u as default};
